// Punto de entrada único para el webhook de Evolution API.
// Decide si el evento es: un mensaje del estudiante, un mensaje escrito por una persona
// desde el teléfono de UnicaU (toma de control), o algo que se ignora.
// US-6: reconoce también fotos y documentos (PDF), que pueden ser comprobantes de pago.
const MARCA_BOT = '\u200B';   // todos los mensajes que envía UnicaU terminan con este carácter invisible
const body = $input.first().json.body ?? {};
const data = body.data ?? {};
const key = data.key ?? {};
const jid = String(key.remoteJid ?? '');

// Grupos, estados, canales: no son conversaciones con estudiantes.
if (!jid || jid.includes('@g.us') || jid.includes('status@broadcast') || jid.includes('@newsletter')) return [];

// Identidad de la persona. WhatsApp a veces entrega un identificador de privacidad
// (xxx@lid) en lugar del número. Evolution API envía además el número real en
// key.remoteJidAlt (v2.3 en adelante) o en key.senderPn (versiones anteriores).
// Si llega un número real (xxx@s.whatsapp.net) se usa ese, en la hoja, en la memoria
// y para responder. Si no llega, se conserva el @lid: es único y estable para esa
// persona, y responderle a él también funciona.
const esNumeroReal = v => /^\d{8,15}@s\.whatsapp\.net$/.test(String(v ?? ''));
const alterno = [key.remoteJidAlt, key.senderPn, data.remoteJidAlt, data.senderPn].find(esNumeroReal);
const jidFinal = jid.endsWith('@lid') && alterno ? alterno : jid;
const telefono = jidFinal.split('@')[0].replace(/\D/g, '');
const destino = jidFinal;   // a dónde se responde
const jid_lid = jid.endsWith('@lid') ? jid : '';   // se guarda por si hace falta rastrear el chat

const tipoWa = data.messageType ?? '';
const m = data.message ?? {};
let texto = '';
if (tipoWa === 'conversation') texto = m.conversation ?? '';
else if (tipoWa === 'extendedTextMessage') texto = m.extendedTextMessage?.text ?? '';
else if (tipoWa === 'imageMessage') texto = m.imageMessage?.caption ?? '';
else if (tipoWa === 'documentMessage') texto = m.documentMessage?.caption ?? '';
else if (tipoWa === 'documentWithCaptionMessage') texto = m.documentWithCaptionMessage?.message?.documentMessage?.caption ?? '';
else if (tipoWa === 'buttonsResponseMessage') texto = m.buttonsResponseMessage?.selectedDisplayText ?? '';
else if (tipoWa === 'listResponseMessage') texto = m.listResponseMessage?.title ?? '';

const IGNORAR = ['protocolMessage','reactionMessage','senderKeyDistributionMessage','messageContextInfo','pollUpdateMessage','editedMessage'];
if (IGNORAR.includes(tipoWa)) return [];

// Ahorro de tokens 1: números que el bot NUNCA atiende con IA. El propio número del bot y
// números de personal u otros asistentes automáticos (evita conversaciones bot-con-bot).
// 573108264135 es otro asistente ("David", cotizaciones quirúrgicas) que estaba configurado
// como si fuera Natalia y respondía a cada aviso.
const NUMEROS_IGNORADOS = ['573180032204', '573108264135', '573234062106'];   // bot, bot ajeno, encargada
if (!key.fromMe && NUMEROS_IGNORADOS.includes(telefono)) return [];

// Ahorro de tokens 2: freno contra ciclos. Si un mismo chat manda más de 10 mensajes en
// 2 minutos, el bot deja de responderle 30 minutos (en silencio, para no alimentar el ciclo).
if (!key.fromMe) {
  const sd = $getWorkflowStaticData('global');
  sd.ritmo = sd.ritmo || {};
  const ahoraMs = Date.now();
  const r = sd.ritmo[telefono] || { t: [], pausaHasta: 0 };
  if (r.pausaHasta > ahoraMs) return [];
  r.t = r.t.filter(x => ahoraMs - x < 120000);
  r.t.push(ahoraMs);
  if (r.t.length > 10) { r.pausaHasta = ahoraMs + 30 * 60000; r.t = []; }
  sd.ritmo[telefono] = r;
  for (const k of Object.keys(sd.ritmo)) {
    const v = sd.ritmo[k];
    if (!v.t.some(x => ahoraMs - x < 120000) && v.pausaHasta < ahoraMs) delete sd.ritmo[k];
  }
  if (r.pausaHasta > ahoraMs) return [];
}

const base = {
  instancia: body.instance ?? '',
  telefono, whatsapp_jid: destino, jid_lid, message_id: key.id ?? '',
  nombre_perfil: data.pushName ?? '',
  recibido: $now.setZone('America/Bogota').toISO(),
};

if (key.fromMe) {
  // Mensajes del propio número: los de UnicaU traen la marca y se ignoran.
  if (!texto.trim() || texto.includes(MARCA_BOT)) return [];
  const reactivar = texto.trim().toUpperCase().includes('ACTIVAR BOT');
  return [{ json: { ...base, evento: 'humano', bot_activo: reactivar ? 'SI' : 'NO' } }];
}

let tipo = 'otro';
if (['conversation','extendedTextMessage','buttonsResponseMessage','listResponseMessage'].includes(tipoWa)) tipo = 'texto';
else if (tipoWa === 'audioMessage') tipo = 'audio';
else if (tipoWa === 'imageMessage') tipo = 'imagen';
else if (tipoWa === 'documentMessage' || tipoWa === 'documentWithCaptionMessage') tipo = 'documento';
const media = m.imageMessage ?? m.documentMessage ?? m.documentWithCaptionMessage?.message?.documentMessage ?? {};
if (tipo === 'texto' && !texto.trim()) return [];

return [{ json: { ...base, evento: 'estudiante', tipo, tipo_whatsapp: tipoWa, texto: texto.trim().slice(0, 1500),
  mimetype: media.mimetype ?? '', nombre_archivo: media.fileName ?? '' } }];

// Una persona escribió desde el teléfono de UnicaU: se pausa el bot en ese chat.
// Si escribió ACTIVAR BOT, se reactiva.
const e = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.pausados = sd.pausados || {};
if (e.bot_activo === 'NO') sd.pausados[e.telefono] = new Date().toISOString();
else delete sd.pausados[e.telefono];
return [];

// ¿Una persona tomó el control de este chat? El estado vive en la memoria interna
// de n8n (static data), no en la hoja. La pausa expira sola para que un chat no
// quede en silencio si nadie escribe ACTIVAR BOT.
const PAUSA_HORAS = 12;
const e = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.pausados = sd.pausados || {};
let activo = true;
const desde = sd.pausados[e.telefono];
if (desde) {
  const horas = (Date.now() - new Date(desde).getTime()) / 36e5;
  if (horas < PAUSA_HORAS) activo = false;
  else delete sd.pausados[e.telefono];
}
return [{ json: { ...e, bot_activo: activo } }];

// Unifica texto y audio transcrito. Función de extracción tomada de Surgical Growths:
// tolera los distintos formatos de salida del nodo OpenAI.
function extraerTexto(json) {
  if (Array.isArray(json)) json = json[0];
  if (!json) return null;
  if (typeof json.text === 'string' && json.text.trim()) return json.text.trim();
  if (typeof json.content === 'string' && json.content.trim()) return json.content.trim();
  if (Array.isArray(json.content) && json.content[0]?.text) {
    const t = json.content[0].text; return (typeof t === 'string' ? t : (t?.value || '')).trim() || null;
  }
  if (typeof json.output_text === 'string' && json.output_text.trim()) return json.output_text.trim();
  return null;
}
const e = $('Estado del chat').first().json;
let texto = e.texto ?? '';
let via = 'texto';
if (e.tipo === 'audio') {
  via = 'audio';
  const t = extraerTexto($input.first().json);
  texto = t ? t.slice(0, 1500) : '[Audio no transcrito: pídele amablemente que lo escriba]';
}
return [{ json: { ...e, texto, via } }];

const raw = String($json.text ?? '').replace(/```json|```/g, '').trim();
let r = { intencion: 'otro', riesgo: false };
try {
  const p = JSON.parse(raw);
  r = { intencion: String(p.intencion || 'otro'), riesgo: p.riesgo === true || p.riesgo === 'true' };
} catch (e) {}
return [{ json: { ...$('Preparar entrada').first().json, ...r } }];

