// Red de seguridad determinística + formato WhatsApp + respaldo si el agente falla.
const t = $('Parsear triage').first().json;
let respuesta = String($json.output ?? '').trim();
if (!respuesta) respuesta = 'Uy, se me enredó algo 🙈 ¿Me lo repites, por favor?';

// Convierte el formato Markdown al formato de WhatsApp
respuesta = respuesta
  .replace(/\*\*(.+?)\*\*/g, '*$1*')                          // **negrita** → *negrita*
  .replace(/__(.+?)__/g, '_$1_')                              // __cursiva__ → _cursiva_
  .replace(/^#{1,6}\s*/gm, '')                                // quita títulos #
  .replace(/^\s*[-*]\s+/gm, '• ')                             // viñetas - o * → •
  .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$1: $2');      // [texto](url) → texto: url

if (t.riesgo && !respuesta.includes('192')) {
  respuesta += '\n\nSi estás en peligro ahora mismo, llama al *123*. También puedes hablar ya con la línea de salud mental *192, opción 4*. 💙';
}
return [{ json: { destino: t.whatsapp_jid, respuesta } }];

// US-9-AC-2 · Si OpenAI (triage o agente) falla, el estudiante recibe un mensaje fijo, sin IA,
// en vez de quedarse sin respuesta. Máximo un aviso cada 10 minutos por chat (evita ciclos y spam).
const c = $('Clasificar evento').first().json;
const sd = $getWorkflowStaticData('global');
sd.fallas = sd.fallas || {};
const ahora = Date.now();
if (ahora - (sd.fallas[c.telefono] || 0) < 10 * 60000) return [];
sd.fallas[c.telefono] = ahora;
for (const k of Object.keys(sd.fallas)) if (ahora - sd.fallas[k] > 3600000) delete sd.fallas[k];
return [{ json: { instancia: c.instancia, destino: c.whatsapp_jid } }];
